// Direction for csr_sweep: Restore writes each CSR from the scratch page
// (ld + csrrw), Drain reads each CSR back to scratch (csrr + sd).
enum class CsrSweepDir { Restore, Drain };

// Program-Buffer CSR sweep: transport a caps-supported list of CSRs between the
// hart and the scratch page. Unlike pb_block_sweep (one uniform ld/st per
// register), a CSR needs TWO instructions -- the CSR number is baked into the
// csrrw/csrr immediate, so it cannot be a runtime operand -- so this batches at
// (progbufsize-1)/2 CSRs per Program-Buffer execution:
//   Restore: ld val,(k*8)(base); csrrw x0, csrs[k], val   (scratch -> CSR)
//   Drain:   csrr val, csrs[k];  sd val,(k*8)(base)       (CSR -> scratch)
// `base` is an integer GPR seeded once with `base_gpa` (the CSR scratch region);
// `val` is a temp GPR the caller may clobber. The values ride the shared scratch
// page (staged/lifted by stage_csr_to_scratch / read_csr_from_scratch), not DMI.
// The csrs list is the caps-supported set in the SAME canonical order the host
// stager packs, so slot k*8 holds csrs[k]'s value. Empty list -> no-op (not even
// the base seed). The k*8 offset spans every slot (<= 81*8 = 648 < 2047).
//
// Every csrs[k] MUST be implemented by the target (the caller builds the list
// from caps): a csrrw/csrr to an unimplemented CSR raises cmderr and exec_progbuf
// throws, aborting the whole batch. That is intentional -- a faulting sweep means
// the caps map is wrong, a config bug to fix, not something to silently mirror.
// To make that bug FIXABLE, a faulting batch is re-run one CSR at a time and the
// thrown error names the offending CSR (re-running is safe: drain reads are
// idempotent, and a restore re-applies the same staged values).
template<typename Bus>
inline void csr_sweep(Bus& bus, uint8_t base_gpr, uint64_t base_gpa,
                      uint8_t val_gpr, std::span<const uint16_t> csrs,
                      CsrSweepDir dir)
{
    if (csrs.empty()) return;
    const uint32_t progbufsize = (bus.read(kDmiAbstractcs) >> 24) & 0x1Fu;
    // Two insns per CSR; reserve one slot for the terminating ebreak. Clamp to
    // the ebreak-adjusted payload cap so a batch never overruns the buffer.
    std::size_t usable = (progbufsize > 1) ? progbufsize - 1u : 1u;
    if (usable > kProgbufMaxInsns) usable = kProgbufMaxInsns;
    const std::size_t max_csrs = (usable >= 2) ? usable / 2u : 1u;
    write_register_abstract(bus, regno_gpr(base_gpr), base_gpa);  // scratch base
    // The (transport; ld/sd) insn pair for csrs[k], shared by the batch build
    // and the fault bisect so both run the identical instructions.

